// CheckoutForm.tsx
import { useEffect, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';

const checkoutSchema = z.object({
  address: z.string().min(1, 'Address is required'),
  card: z.string().min(1, 'Card number is required'),
});

type CheckoutFormData = z.infer<typeof checkoutSchema>;

interface CheckoutFormProps {
  onSubmit: (data: CheckoutFormData) => void;
}

export function CheckoutForm({ onSubmit }: CheckoutFormProps) {
  const [step, setStep] = useState(1);
  const { register, handleSubmit, setError, formState: { errors } } = useForm<CheckoutFormData>();
  const stepHeadingRef = useRef<HTMLLegendElement>(null);

  useEffect(() => {
    stepHeadingRef.current?.focus();
  }, [step]);

  const onValidSubmit = (data: CheckoutFormData) => {
    const result = checkoutSchema.safeParse(data);
    if (!result.success) {
      for (const issue of result.error.issues) {
        setError(issue.path[0] as keyof CheckoutFormData, { message: issue.message });
      }
      return;
    }
    onSubmit(result.data);
  };

  return (
    <form onSubmit={handleSubmit(onValidSubmit)} className="max-w-md mx-auto space-y-4">
      <div aria-live="polite" className="sr-only">Step {step} of 3</div>
      {step === 1 && (
        <fieldset className="space-y-2">
          <legend ref={stepHeadingRef} tabIndex={-1} className="font-medium outline-none">Shipping</legend>
          <label htmlFor="address" className="block text-sm font-medium">Address</label>
          <input id="address" {...register('address')} className="w-full border rounded-md px-3 py-2" />
          {errors.address && <p role="alert" className="text-sm text-red-600">{errors.address.message}</p>}
        </fieldset>
      )}
      {step === 2 && (
        <fieldset className="space-y-2">
          <legend ref={stepHeadingRef} tabIndex={-1} className="font-medium outline-none">Payment</legend>
          <label htmlFor="card" className="block text-sm font-medium">Card number</label>
          <input id="card" {...register('card')} className="w-full border rounded-md px-3 py-2" />
          {errors.card && <p role="alert" className="text-sm text-red-600">{errors.card.message}</p>}
        </fieldset>
      )}
      {step === 3 && (
        <fieldset className="space-y-2">
          <legend ref={stepHeadingRef} tabIndex={-1} className="font-medium outline-none">Review</legend>
          <button
            type="submit"
            className="w-full text-white rounded-md py-2"
            style={{ backgroundColor: 'var(--color-brand-primary, #000000)' }}
          >
            Place order
          </button>
        </fieldset>
      )}
      <div className="flex justify-between">
        {step > 1 && <button type="button" onClick={() => setStep(step - 1)}>Back</button>}
        {step < 3 && <button type="button" onClick={() => setStep(step + 1)}>Next</button>}
      </div>
    </form>
  );
}

