// CommandPalette.tsx
import { Command } from 'cmdk';

export interface CommandPaletteCommand {
  id: string;
  label: string;
  action: () => void;
}

interface CommandPaletteProps {
  commands: CommandPaletteCommand[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CommandPalette({ commands, open, onOpenChange }: CommandPaletteProps) {
  return (
    <Command.Dialog
      open={open}
      onOpenChange={onOpenChange}
      label="Command palette"
      overlayClassName="fixed inset-0 bg-[var(--color-surface-overlay,rgba(0,0,0,0.4))]"
      contentClassName="rounded-lg"
    >
      <Command.Input placeholder="Type a command..." />
      <Command.List>
        {commands.map((c) => (
          <Command.Item key={c.id} onSelect={c.action}>{c.label}</Command.Item>
        ))}
      </Command.List>
    </Command.Dialog>
  );
}
